import os, re

FILES = []
for root, dirs, fs in os.walk('.'):
    for fn in fs:
        if fn.endswith('.md'):
            FILES.append(os.path.join(root, fn))

print(f'Total .md files: {len(FILES)}')

# 1. Headings - find lines with # prefix
print('\n=== ALL MARKDOWN HEADINGS ===')
for f in sorted(FILES):
    with open(f, 'r', encoding='utf-8') as fh:
        text = fh.read()
    for i, line in enumerate(text.splitlines(), 1):
        if re.match(r'^#{1,6}\s+\S', line):
            print(f'{f}:{i}: {line[:100]}')

# 2. Code fences
print('\n=== ALL ``` BLOCKS (open/close) ===')
for f in sorted(FILES):
    with open(f, 'r', encoding='utf-8') as fh:
        for i, line in enumerate(fh, 1):
            if line.lstrip().startswith('\u0060\u0060\u0060'):
                opens = line.rstrip()
                print(f'{f}:{i}: {opens}')

# 3. Frontmatter
print('\n=== FRONTMATTER ===')
for f in sorted(FILES):
    with open(f, 'r', encoding='utf-8') as fh:
        first = fh.readline()
        if first.strip() == '---':
            print(f'{f}: HAS FRONTMATTER')
        else:
            print(f'{f}: NO FRONTMATTER (first line: {first[:50]!r})')

# 4. Tables
print('\n=== TABLES (lines starting with |) ===')
for f in sorted(FILES):
    with open(f, 'r', encoding='utf-8') as fh:
        for i, line in enumerate(fh, 1):
            if line.startswith('|'):
                print(f'{f}:{i}: {line.rstrip()[:80]}')

# 5. Image refs ![[ ]]
print('\n=== IMAGE REFS ===')
for f in sorted(FILES):
    with open(f, 'r', encoding='utf-8') as fh:
        for i, line in enumerate(fh, 1):
            for m in re.finditer(r'!\[\[[^\]]+\]\]', line):
                print(f'{f}:{i}: {m.group()}')

# 6. HTML tags
print('\n=== HTML-LIKE TAGS ===')
for f in sorted(FILES):
    with open(f, 'r', encoding='utf-8') as fh:
        for i, line in enumerate(fh, 1):
            for m in re.finditer(r'<[a-zA-Z]+(?:\s|>|/>)', line):
                # skip when clearly code (delimiters check)
                tag = m.group().rstrip(' >/')
                print(f'{f}:{i}: {m.group()}')

# 7. Bold/italic markers
print('\n=== BOLD/ITALIC ===')
for f in sorted(FILES):
    with open(f, 'r', encoding='utf-8') as fh:
        for i, line in enumerate(fh, 1):
            for m in re.finditer(r'\*\*[^\*\s][^*]*?\*\*', line):
                if '<' not in line[:m.start()]:  # skip Javadoc
                    print(f'{f}:{i}: BOLD: {m.group()}')
            for m in re.finditer(r'(?<!\*)\*[^\*\s][^*]*?\*(?!\*)', line):
                print(f'{f}:{i}: ITALIC: {m.group()}')

# 8. Numbered list & bullet list
print('\n=== NUMBERED LISTS / BULLET LISTS ===')
for f in sorted(FILES):
    with open(f, 'r', encoding='utf-8') as fh:
        for i, line in enumerate(fh, 1):
            if re.match(r'^\d+\.\s', line):
                print(f'{f}:{i}: NUM: {line.rstrip()[:60]}')
            elif re.match(r'^[-*+]\s', line):
                print(f'{f}:{i}: BUL: {line.rstrip()[:60]}')

# 9. Tables check: balanced open/close fences
print('\n=== FENCE BALANCE CHECK ===')
for f in sorted(FILES):
    with open(f, 'r', encoding='utf-8') as fh:
        text = fh.read()
    count = len(re.findall(r'^\u0060\u0060\u0060', text, flags=re.MULTILINE))
    if count % 2 != 0:
        print(f'{f}: UNBALANCED {count} fences')
    else:
        if count > 0:
            print(f'{f}: {count} fences (balanced)')

